function spiralSurvey(matrix) {
  const h = matrix.length, w = matrix[0].length, seen = new Set(), out = [];
  const dirs = [[0, 1], [1, 0], [0, -1], [-1, 0]];
  let r = 0, c = 0, d = 0;
  for (let k = 0; k < h * w; k++) {
    out.push(matrix[r][c]);
    seen.add(r * w + c);
    let nr = r + dirs[d][0], nc = c + dirs[d][1];
    if (nr < 0 || nr >= h || nc < 0 || nc >= w || seen.has(nr * w + nc)) {
      d = (d + 1) % 4;
      nr = r + dirs[d][0];
      nc = c + dirs[d][1];
    }
    r = nr;
    c = nc;
  }
  return out;
}

